#!/usr/bin/env python3
"""Expand @path imports from ~/.codex/AGENTS.md into AGENTS.override.md."""

from __future__ import annotations

import argparse
import os
import re
import sys
import tempfile
from pathlib import Path


INCLUDE_RE = re.compile(r"(?P<prefix>^|\s)@(?P<path>(?:[^\s\\]|\\ )+)")
FENCE_RE = re.compile(r"^[ \t]*(```+|~~~+)")
TEXT_FILE_EXTENSIONS = {
    ".md",
    ".markdown",
    ".mdown",
    ".txt",
    ".text",
}
DEFAULT_SOURCE = Path.home() / ".codex" / "AGENTS.md"
DEFAULT_OUTPUT = Path.home() / ".codex" / "AGENTS.override.md"
GENERATED_HEADER = "<!-- Generated by markdown-imports. Edit AGENTS.md, not this file. -->"


class ImportErrorWithPath(Exception):
    pass


def resolve_import(raw_path: str, base_dir: Path) -> Path:
    path = raw_path.strip()
    hash_index = path.find("#")
    if hash_index != -1:
        path = path[:hash_index]
    path = path.replace("\\ ", " ")
    if not path:
        raise ImportErrorWithPath("empty import path")
    if path.startswith("~/"):
        return Path.home() / path[2:]
    candidate = Path(os.path.expandvars(path)).expanduser()
    if not candidate.is_absolute():
        candidate = base_dir / candidate
    return candidate.resolve()


def is_valid_import_path(path: str) -> bool:
    if Path(path).suffix.lower() not in TEXT_FILE_EXTENSIONS:
        return False
    if path.startswith(("./", "~/")):
        return True
    if path.startswith("/") and path != "/":
        return True
    if path.startswith("@") or re.match(r"^[#%^&*()]+", path):
        return False
    return bool(re.match(r"^[a-zA-Z0-9._-]", path))


def find_imports(line: str) -> list[tuple[str, Path | None]]:
    masked = re.sub(r"`[^`\n]*`", lambda match: " " * len(match.group(0)), line)
    imports: list[tuple[str, Path | None]] = []
    for match in INCLUDE_RE.finditer(masked):
        raw_path = match.group("path")
        candidate = raw_path.split("#", 1)[0].replace("\\ ", " ")
        if is_valid_import_path(candidate):
            imports.append((raw_path, None))
    return imports


def expand_file(path: Path, stack: list[Path], processed: set[Path]) -> str:
    resolved = path.resolve()
    if resolved in stack:
        cycle = " -> ".join(str(item) for item in [*stack, resolved])
        raise ImportErrorWithPath(f"import cycle detected: {cycle}")
    if resolved in processed:
        return ""
    if not resolved.is_file():
        raise ImportErrorWithPath(f"import target does not exist: {resolved}")
    if resolved.suffix.lower() not in TEXT_FILE_EXTENSIONS:
        raise ImportErrorWithPath(f"import target is not a supported text file: {resolved}")

    processed.add(resolved)
    stack.append(resolved)
    try:
        result: list[str] = []
        in_fence = False
        text = resolved.read_text(encoding="utf-8")
        for line in text.splitlines(keepends=True):
            if FENCE_RE.match(line):
                in_fence = not in_fence
                result.append(line)
                continue
            if in_fence:
                result.append(line)
                continue

            newline = "\n" if line.endswith("\n") else ""
            body = line[:-1] if newline else line
            imports = find_imports(body)
            if not imports:
                result.append(line)
                continue

            standalone = len(imports) == 1 and body.strip() == f"@{imports[0][0]}"
            for raw_path, _ in imports:
                import_path = resolve_import(raw_path, resolved.parent)
                imported = expand_file(import_path, stack, processed)
                if not imported:
                    continue
                result.append(f"<!-- begin import: {import_path} -->\n")
                result.append(imported)
                if not imported.endswith("\n"):
                    result.append("\n")
                result.append(f"<!-- end import: {import_path} -->{newline}")
            if not standalone:
                result.append(line)
        return "".join(result)
    finally:
        stack.pop()


def write_atomic(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp_name = tempfile.mkstemp(
        prefix=f".{path.name}.",
        suffix=".tmp",
        dir=str(path.parent),
        text=True,
    )
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(content)
        os.replace(tmp_name, path)
    finally:
        if os.path.exists(tmp_name):
            os.unlink(tmp_name)


def write_if_changed(path: Path, content: str) -> bool:
    if path.exists() and path.read_text(encoding="utf-8") == content:
        return False
    write_atomic(path, content)
    return True


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Expand @path imports in ~/.codex/AGENTS.md.",
    )
    parser.add_argument("--source", type=Path, default=DEFAULT_SOURCE)
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    parser.add_argument(
        "--check",
        action="store_true",
        help="Fail if the generated output would change.",
    )
    args = parser.parse_args()

    try:
        expanded = expand_file(args.source.expanduser(), [], set())
    except ImportErrorWithPath as exc:
        print(f"markdown-imports: {exc}", file=sys.stderr)
        return 1

    content = f"{GENERATED_HEADER}\n\n{expanded}"
    output = args.output.expanduser()

    if args.check:
        if not output.exists():
            print(f"markdown-imports: missing generated file: {output}", file=sys.stderr)
            return 1
        current = output.read_text(encoding="utf-8")
        if current != content:
            print(f"markdown-imports: generated file is stale: {output}", file=sys.stderr)
            return 1
        return 0

    if write_if_changed(output, content):
        print(f"markdown-imports: updated {output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

